.ds {
  --ds-bg:var(--p-bg,#ffffff); --ds-surface:var(--p-surface,#f1f3f6); --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d); --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5); --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de); --ds-accent:var(--p-accent,#303b48); --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5); --ds-error:var(--p-error,#a3313e); --ds-success:var(--p-success,#26614f); --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px); --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166,-5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066,-3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55,inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8); --ds-disabled:var(--p-disabled,#dce1e8); --ds-duration:var(--p-duration,140ms);
  --ds-font:Pretendard,sans-serif; --ds-display-font:Outfit,Pretendard,sans-serif;
  --ds-text-sm:13px; --ds-text-md:16px; --ds-text-lg:24px;
  --ds-space-1:4px; --ds-space-2:8px; --ds-space-3:12px; --ds-space-4:16px; --ds-space-6:24px; --ds-space-8:32px;
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,170px),1fr)); gap:var(--ds-space-6); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:14px; font-weight:600; margin-bottom:var(--ds-space-3); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--ds-space-3); min-height:44px; width:fit-content; padding-inline:4px; cursor:pointer; font-size:14px; }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:22px; height:22px; border:1.5px solid var(--ds-control-border); border-radius:7px; background:var(--ds-bg); box-shadow:var(--ds-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--ds-accent); border-color:var(--ds-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:6px; height:10px; left:6px; top:2px; border:solid #fff; border-width:0 2px 2px 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:10px; height:2px; left:4px; top:8px; background:#fff; transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:50%; }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:5px; background:#fff; border-radius:50%; }
.ds .ds-choice:has(:disabled) { color:var(--ds-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:1; background:var(--ds-disabled); border-color:var(--ds-border); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--ds-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--ds-muted); }
.ds .ds-choice .ds-switch { width:44px; height:26px; border-radius:24px; }
.ds .ds-switch::before { content:''; position:absolute; top:3px; left:3px; width:18px; height:18px; border-radius:50%; background:var(--ds-muted); box-shadow:0 1px 3px #26344726; transition:left var(--ds-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:21px; background:#fff; }
.ds .ds-switch:disabled::before { background:var(--ds-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}

'use client';
import React, { useEffect, useRef } from 'react';
export function Checkbox({ children, indeterminate = false, ...props }) {
  const ref = useRef(null);
  useEffect(() => { ref.current.indeterminate = indeterminate; }, [indeterminate]);
  return <label className="ds-choice"><input {...props} ref={ref} type="checkbox" />{children}</label>;
}

